const mono='Orbitron, monospace', body='Rajdhani, sans-serif';
type Payload={ok:boolean;frontiers:ResearchFrontier[];jobs:CrawlJob[];summary?:CatalogueSummary;pages?:CataloguePage[];error?:string};
type CaptureClient={client_id:string;label:string;extension_origin:string;status:'pending'|'approved'|'revoked';approved_at?:string|null;last_seen_at?:string|null;created_at:string};
