type RecordPerson={person_index:number;role:string;name_raw:string;name_pattern:string|null;reconstructed_name:string|null;reconstruction_basis:string|null;given_names:string|null;surname:string|null;surname_raw:string|null;surname_pattern:string|null;reconstructed_surname:string|null;surname_reconstruction_basis:string|null;surname_visual_confidence:number|null;surname_contextual_confidence:number|null;surname_state:'visible'|'partial'|'reconstructed'|'absent'|'unknown';residence:string|null;occupation:string|null;confidence:number;visual_confidence:number|null;contextual_confidence:number|null};
type StructuredRecord={id:number;page_id:number;page_number:number|null;entry_order:number|null;event_type:string;event_date_text:string|null;event_year:number|null;date_visual_text:string|null;date_source:string|null;date_inferred:boolean;location_text:string|null;subject_text:string|null;formula_template:string|null;confidence:number;visual_confidence:number|null;contextual_confidence:number|null;boundary_confidence:number|null;review_status:string;source_url:string;people:RecordPerson[];relationships:Array<{type:string;from_name:string|null;to_name:string|null;confidence:number}>};
type NameAlternative=string|{reading?:string;text?:string;confidence?:number};
type NameReading={id:number;page_id:number;page_number:number|null;source_url:string;sha256:string|null;tile_id:string;role_hint:string;reading_type:string;page_type:string|null;name_raw:string;normalized_name:string;alternatives:NameAlternative[];context_excerpt:string|null;letter_evidence:string|null;confidence:number;review_status:string;consensus_name:string|null;consensus_variants:string[]|null;supporting_pages:number[]|null;support_count:number|null;consensus_confidence:number|null;consensus_metadata:{page_support?:number;cross_page?:boolean}|null;search_rank:number};
