function record(value:unknown):value is Record<string,unknown>{return !!value && typeof value==='object' && !Array.isArray(value);}
const textFields=(value:Record<string,unknown>,keys:string[])=>keys.every(key=>typeof value[key]==='string');
const stringList=(value:unknown)=>Array.isArray(value) && value.every(item=>typeof item==='string');
const numberFields=(value:Record<string,unknown>,keys:string[])=>keys.every(key=>Number.isSafeInteger(value[key]) && Number(value[key])>=0);
// Neon preserves BIGSERIAL as decimal text. Only exact safe IDs can enter numeric UI actions.
const safeId=(value:unknown)=>Number.isSafeInteger(value) && Number(value)>0 || typeof value==='string' && /^[1-9]\d*$/.test(value) && Number.isSafeInteger(Number(value));

export function normalizeGenealogyCatalogue(value:unknown,httpOk:boolean,status:number):Payload{
  const unavailable:Payload={ok:false,frontiers:[],jobs:[],pages:[],
    error:`The genealogy catalogue could not be verified${!httpOk && status>=100?` (HTTP ${status})`:''}. Refresh its status before continuing.`};
  if(!httpOk || !record(value) || value.ok!==true || !Array.isArray(value.frontiers) || !Array.isArray(value.jobs))return unavailable;
  if(!value.frontiers.every(item=>record(item) && textFields(item,['id','branch','person','objective','place','priority','rationale']) && stringList(item.variants)
      && (item.yearFrom===undefined || Number.isSafeInteger(item.yearFrom)) && (item.yearTo===undefined || Number.isSafeInteger(item.yearTo))))return unavailable;
  if(!value.jobs.every(item=>record(item) && safeId(item.id) && numberFields(item,['pages_discovered','pages_downloaded','pages_scanned']) && textFields(item,['status','objective'])))return unavailable;
  if(value.summary!==undefined && (!record(value.summary) || !numberFields(value.summary,['pages','enhanced','scan_runs','indexed_pages','observations','needs_review'])))return unavailable;
  if(value.pages!==undefined && (!Array.isArray(value.pages) || !value.pages.every(item=>record(item)
      && safeId(item.id) && numberFields(item,['variant_count','scan_count','observation_count']) && textFields(item,['source_url','status'])
      && (item.page_number===null || Number.isSafeInteger(item.page_number))
      && (item.sha256===null || typeof item.sha256==='string')
      && (item.index_status===undefined || typeof item.index_status==='string')
      && (item.index_names===undefined || stringList(item.index_names))
      && (item.index_terms===undefined || stringList(item.index_terms))
      && (item.index_year_from==null || Number.isSafeInteger(item.index_year_from))
      && (item.index_year_to==null || Number.isSafeInteger(item.index_year_to)))))return unavailable;
  return {ok:true,frontiers:value.frontiers as ResearchFrontier[],jobs:value.jobs.map(item=>({...item,id:Number(item.id)})) as CrawlJob[],
    summary:value.summary as CatalogueSummary|undefined,pages:((value.pages??[]) as CataloguePage[]).map(item=>({...item,id:Number(item.id)}))};
}

export function normalizeGenealogyAcquisition(value:unknown,httpOk:boolean):AcquisitionPayload|null{
  if(!httpOk || !record(value) || value.ok!==true || !Array.isArray(value.clients) || !Array.isArray(value.assets)
      || !record(value.summary) || !numberFields(value.summary,['assets'])
      || !(Number.isSafeInteger(value.summary.bytes) && Number(value.summary.bytes)>=0 || typeof value.summary.bytes==='string' && /^\d+$/.test(value.summary.bytes)))return null;
  if(!value.clients.every(item=>record(item) && textFields(item,['client_id','label','extension_origin','status'])
      && ['pending','approved','revoked'].includes(String(item.status)) && (item.last_seen_at==null || typeof item.last_seen_at==='string')))return null;
  return {ok:true,clients:value.clients as CaptureClient[],assets:value.assets as ArchiveAsset[],summary:value.summary as AcquisitionPayload['summary']};
}

async function readApiJson(response:Response){
  const text=await response.text();
  if(!text.trim())throw new Error(`Mastermind returned an empty response (HTTP ${response.status}). Please try once more.`);
  try{return JSON.parse(text);}catch{throw new Error(`Mastermind returned an unreadable response (HTTP ${response.status}).`);}
}

